func validateSemanticProviderPath(providerPath string) (string, error) {
	if providerPath == "" {
		return "", nil
	}
	if strings.Contains(providerPath, "\\") {
		return "", fmt.Errorf("semantic provider path must use slash separators: %s", providerPath)
	}
